     3	  <head>
     4	    <title>jQuery json-viewer</title>
     5	    <meta charset="utf-8" />
     6	    <script src="https://code.jquery.com/jquery-3.3.1.min.js"></script>
     7	    <script src="json-viewer/jquery.json-viewer.js"></script>
     8	    <link href="json-viewer/jquery.json-viewer.css" type="text/css" rel="stylesheet">
     9	
    10	    <style type="text/css">
    11	body {
    12	  margin: 0 100px;
    13	  font-family: sans-serif;
    14	}
    15	p.options label {
    16	  margin-right: 10px;
    17	}
    18	p.options input[type=checkbox] {
    19	  vertical-align: middle;
    20	}
    21	textarea#json-input {
    22	  width: 100%;
    23	  height: 200px;
    24	}
    25	pre#json-renderer {
    26	  border: 1px solid #aaa;
    27	}
    28	    </style>
    29	
    30	    <script>
    31	$(function() {
    32	  function renderJson() {
    33	    try {
    34	      var input = eval('(' + $('#json-input').val() + ')');
    35	    }
    36	    catch (error) {
    37	      return alert("Cannot eval JSON: " + error);
    38	    }
    39	    var options = {
    40	      collapsed: $('#collapsed').is(':checked'),
    41	      rootCollapsable: $('#root-collapsable').is(':checked'),
    42	      withQuotes: $('#with-quotes').is(':checked'),
    43	      withLinks: $('#with-links').is(':checked')
    44	    };
    45	    $('#json-renderer').jsonViewer(input, options);
    46	  }
    47	
    48	  // Generate on click
    49	  $('#btn-json-viewer').click(renderJson);
    50	
    51	  // Generate on option change
    52	  $('p.options input[type=checkbox]').click(renderJson);
    53	
    54	  // Display JSON sample on page load
    55	  renderJson();
    56	});
    57	    </script>
    58	  </head>
    59	  <body>
    60	    <h1><a href="https://github.com/abodelot/jquery.json-viewer">jQuery json-viewer</a></h1>
    61	    <textarea id="json-input" autocomplete="off">
    62	{
    63	  "id": 1001,
    64	  "type": "donut",
    65	  "name": "Cake",
    66	  "description": "https://en.wikipedia.org/wiki/Doughnut",
    67	  "price": 2.55,
    68	  "available": {
    69	    store: 42,
    70	    warehouse: 600
    71	  },
    72	  "toppings": [
    73	    { "id": 5001, "type": "None" },
    74	    { "id": 5002, "type": "Glazed" },
    75	    { "id": 5005, "type": "Sugar" },
    76	    { "id": 5003, "type": "Chocolate" },
    77	    { "id": 5004, "type": "Maple" }
    78	  ],
    79	  "uuids": [
    80	    "826b23ce-2669-4122-981f-3e2e4429159d",
    81	    "e32111a0-6a87-49ab-b58f-a01bf8d28ba0",
    82	    "c055a894-698e-41c0-b85f-7510a7351d9d",
    83	  ],
    84	}</textarea>
    85	    <p class="options">
    86	      Options:
    87	      <label title="Generate node as collapsed">
    88	        <input type="checkbox" id="collapsed">Collapse nodes
    89	      </label>
    90	      <label title="Allow root element to be collasped">
    91	        <input type="checkbox" id="root-collapsable" checked>Root collapsable
    92	      </label>
    93	      <label title="Surround keys with quotes">
    94	        <input type="checkbox" id="with-quotes">Keys with quotes
    95	      </label>
    96	      <label title="Generate anchor tags for URL values">
    97	        <input type="checkbox" id="with-links" checked>
    98	        With Links
    99	      </label>
   100	    </p>
   101	    <button id="btn-json-viewer" title="run jsonViewer()">Transform to HTML</button>
   102	    <pre id="json-renderer"></pre>
   103	  </body>
   104	</html>
